/**
 * @name Taint through JMESPath expression evaluation into function registry
 * @description Detects untrusted data flowing into expression evaluation that might call custom functions.
 * @kind path-problem
 * @problem.severity warning
 * @id py/jmespath-untrusted-expression
 * @tags security
 *       external/cwe/cwe-094
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.ApiGraphs

module JMESPathExprConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    exists(API::CallNode call |
      call = API::moduleImport("jmespath").getMember(["search", "compile"]).getACall() and
      sink = call.getArg(0)
    )
  }
}

module JMESPathExprFlow = TaintTracking::Global<JMESPathExprConfig>;
import JMESPathExprFlow::PathGraph

from JMESPathExprFlow::PathNode source, JMESPathExprFlow::PathNode sink
where JMESPathExprFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Untrusted data is used as a JMESPath expression $@.", sink.getNode(), "expression"

/**
 * @name Tainted data flowing into json.load/loads
 * @description Detects user-controlled data flowing into json.loads/json.load which may lead to injection or parsing issues.
 * @kind path-problem
 * @problem.severity warning
 * @id py/tainted-json-load
 * @tags security
 *       external/cwe/cwe-020
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.ApiGraphs

module JsonTaintConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    exists(API::CallNode call |
      call = API::moduleImport("json").getMember(["load", "loads"]).getACall() and
      sink = call.getArg(0)
    )
  }
}

module JsonTaintFlow = TaintTracking::Global<JsonTaintConfig>;
import JsonTaintFlow::PathGraph

from JsonTaintFlow::PathNode source, JsonTaintFlow::PathNode sink
where JsonTaintFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "User-controlled data flows into json load function $@.", sink.getNode(), "json input"
